<script setup lang="ts">
import { Plus, UserRoundCheck } from "@lucide/vue";
import { onMounted, ref } from "vue";
import { apiRequest } from "@/services/api";
import { useSessionStore } from "@/stores/session";
interface ManagedUser { name: string; full_name: string; enabled: number; lgas: string[]; roles: string[] }
const session = useSessionStore(); const users = ref<ManagedUser[]>([]); const loading = ref(true); const showForm = ref(false); const error = ref("");
const form = ref({ email: "", first_name: "", last_name: "", role: "HR Officer", company: session.activeLga, temporary_password: "" });
async function loadUsers() { loading.value = true; try { users.value = (await apiRequest<{items: ManagedUser[]}>("/api/method/dtmgp.api.v1.users.list_users")).items; } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to load users"; } finally { loading.value = false; } }
async function createUser() { try { await apiRequest("/api/method/dtmgp.api.v1.users.create_user", { method: "POST", body: JSON.stringify(form.value) }); showForm.value = false; await loadUsers(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to create user"; } }
async function toggleUser(user: ManagedUser) { await apiRequest("/api/method/dtmgp.api.v1.users.set_user_enabled", { method: "POST", body: JSON.stringify({ user: user.name, enabled: user.enabled ? 0 : 1 }) }); await loadUsers(); }
onMounted(loadUsers);
</script>
<template><section class="page-heading"><div><p class="eyebrow">Administration</p><h1>User management</h1><p>{{ session.canChangeLga ? "Statewide user access" : session.activeLga }}</p></div><button v-if="session.canManageUsers" class="primary-action" @click="showForm = true"><Plus :size="17" /> Add user</button></section><section class="users-panel"><p v-if="error" class="login-error">{{ error }}</p><p v-if="loading" class="users-empty">Loading users...</p><div v-else class="user-list"><article v-for="user in users" :key="user.name"><span class="user-list-avatar"><UserRoundCheck :size="20" /></span><div><strong>{{ user.full_name }}</strong><small>{{ user.name }}</small></div><span>{{ user.roles.join(", ") || "Staff" }}</span><span>{{ user.lgas.map(lga => lga.replace(" Local Government Area", " LGA")).join(", ") }}</span><button class="secondary-action" @click="toggleUser(user)">{{ user.enabled ? "Disable" : "Enable" }}</button></article><p v-if="!users.length" class="users-empty">No users found in your LGA.</p></div></section><div v-if="showForm" class="modal-backdrop" @click.self="showForm = false"><form class="user-modal" @submit.prevent="createUser"><h2>Add staff user</h2><label>Email<input v-model="form.email" type="email" required /></label><label>First name<input v-model="form.first_name" required /></label><label>Last name<input v-model="form.last_name" /></label><label>Role<select v-model="form.role"><option v-for="role in ['LGA Administrator','LGA Secretary','Treasurer','HR Officer','Procurement Officer','Project Officer','Traditional Affairs Officer','Internal Auditor','Read-only Officer']" :key="role">{{ role }}</option></select></label><label>LGA<select v-model="form.company" :disabled="!session.canChangeLga"><option v-for="lga in session.allowedLgas" :key="lga">{{ lga }}</option></select></label><label>Temporary password<input v-model="form.temporary_password" type="password" minlength="8" /></label><p v-if="error" class="login-error">{{ error }}</p><footer><button type="button" class="secondary-action" @click="showForm = false">Cancel</button><button class="primary-action">Create user</button></footer></form></div></template>
